import{_ as a,c as i,o as n,b0 as e}from"./chunks/framework.BWMBvyU7.js";const p="/programming-docs/assets/image-20221117221142069.Bxy6WIKo.png",l="/programming-docs/assets/7be417ea2a4c46466ff35f2bfeb741a1.CQrMQLjf.png",t="/programming-docs/assets/b184e33db8c42f78c5cebe10160092c1.CB325flG.png",r="/programming-docs/assets/92bcb7acbb591d2db4a364f7330eaccc.C_DTZ6Xq.png",h="/programming-docs/assets/01.B8BYKnCc.png",u=JSON.parse('{"title":"LV005-虚拟内存简介","description":null,"frontmatter":{"title":"LV005-虚拟内存简介","date":"2026-03-16T21:40:50.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/os/memory/126d38f373221b0e42546131","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-03-16T21:40:50.432Z","fulluuid":"e425461319c34a0ca346926377a31463","useduuid":"e42546131"}},"headers":[],"relativePath":"sdoc/os/memory/126d38f373221b0e42546131.md","filePath":"sdoc/03-操作系统/11-内存管理/LV005-虚拟内存简介.md","lastUpdated":1773672539000}'),o={name:"sdoc/os/memory/126d38f373221b0e42546131.md"};function d(c,s,k,g,m,b){return n(),i("div",null,[...s[0]||(s[0]=[e('<h1 id="lv005-虚拟内存简介" tabindex="-1">LV005-虚拟内存简介 <a class="header-anchor" href="#lv005-虚拟内存简介" aria-label="Permalink to &quot;LV005-虚拟内存简介&quot;">​</a></h1><p>看到这篇文章：<a href="https://mp.weixin.qq.com/s?__biz=MzUxODAzNDg4NQ==&amp;mid=2247522087&amp;idx=2&amp;sn=fe8f4cd34d68e0a10658dee88bd337df&amp;chksm=f98dd38dcefa5a9ba43a9d1ac96852532f53278915a6f6b9f5187b8c1c885c1e5848ebabbc86&amp;mpshare=1&amp;scene=23&amp;srcid=11063jZmSPqRgcXsIvaADdki&amp;sharer_sharetime=1668693824030&amp;sharer_shareid=4daf4f8ac44b01cb81e6e5beec11fe8b#rd" target="_blank" rel="noreferrer">3.5 万字 + 60 张图 ｜一步一图带你深入理解 Linux 虚拟内存管理 (qq.com)</a>，真的是讲解的特别详细，推荐看原文，自己在这里做一个笔记，也是对自己的一个提升了。</p><h2 id="一、什么是虚拟内存地址" tabindex="-1">一、什么是虚拟内存地址 <a class="header-anchor" href="#一、什么是虚拟内存地址" aria-label="Permalink to &quot;一、什么是虚拟内存地址&quot;">​</a></h2><h3 id="_1-虚拟地址" tabindex="-1">1. 虚拟地址？ <a class="header-anchor" href="#_1-虚拟地址" aria-label="Permalink to &quot;1. 虚拟地址？&quot;">​</a></h3><p>这里沿用大佬文章的例子，每年双十一，很多人，包括我哈，都免不了一顿买买买的操作，我们都是采用网购的方式，物品下单后，我们会填上我们的收货人联系方式，收货人信息：</p><img src="'+p+'" alt="image-20221117221142069" style="zoom:33%;"><p>随后我们就在家里静等商品啦，快递员就会根据我们填写的收货地址找到我们的真实住所，将我们网购的商品送达到我们的手里。</p><p>收货地址是用来<strong>定位</strong>我们在现实世界中<strong>真实住所地理位置</strong>的，而现实世界中我们所在的城市，街道，小区，房屋都是一砖一瓦，一草一木都是真实存在的。但收货地址这个概念模型在现实世界中并不真实存在，它只是人们提出的一个虚拟概念，通过<strong>收货地址</strong>这个虚拟概念将它和现实世界真实存在的城市，小区，街道的地理位置<strong>一一映射</strong>起来，这样我们就可以<strong>通过这个虚拟概念来找到现实世界中的具体的地理位置</strong>。</p><p>所以，这样来看，收货地址是一个虚拟地址，它是人为定义的，而我们的城市，小区，街道是真实存在的，他们的地理位置就是物理地址。</p><h3 id="_2-庐山真面目" tabindex="-1">2. 庐山真面目？ <a class="header-anchor" href="#_2-庐山真面目" aria-label="Permalink to &quot;2. 庐山真面目？&quot;">​</a></h3><p>现在让我们把视角在切换到计算机的世界，在计算机的世界里内存地址用来定义数据在内存中的存储位置的，内存地址也分为虚拟地址和物理地址。而虚拟地址也是人为设计的一个概念，类比我们现实世界中的收货地址，而物理地址则是数据在物理内存中的真实存储位置，类比现实世界中的城市，街道，小区的真实地理位置。</p><p>那么到底虚拟内存地址长什么样子呢？我们还是以日常生活中的收货地址为例做类比，我们都很熟悉收货地址的格式：xx省xx市xx区xx街道xx小区xx室，它是按照地区层次递进的。同样，在计算机世界中的虚拟内存地址也有这样的递进关系。</p><p>这里我们以 Intel Core i7 处理器为例，64 位虚拟地址的格式为：全局页目录项（9位）+ 上层页目录项（9位）+ 中间页目录项（9位）+ 页内偏移（12位）。共 48 位组成的虚拟内存地址。</p><img src="'+l+'" alt="image.png" style="zoom:50%;"><p>虚拟内存地址中的全局页目录项就类比我们日常生活中收获地址里的省，上层页目录项就类比市，中间层页目录项类比区县，页表项类比街道小区，页内偏移类比我们所在的楼栋和几层几号。</p><p>32 位虚拟地址的格式为：页目录项（10位）+ 页表项（10位） + 页内偏移（12位）。共 32 位组成的虚拟内存地址。</p><img src="'+t+`" alt="image.png" style="zoom:50%;"><p><strong>进程虚拟内存空间中的每一个字节都有与其对应的虚拟内存地址，一个虚拟内存地址表示进程虚拟内存空间中的一个特定的字节</strong>。</p><h2 id="二、为什么要用虚拟内存地址" tabindex="-1">二、为什么要用虚拟内存地址？ <a class="header-anchor" href="#二、为什么要用虚拟内存地址" aria-label="Permalink to &quot;二、为什么要用虚拟内存地址？&quot;">​</a></h2><h3 id="_1-直接使用物理内存" tabindex="-1">1. 直接使用物理内存？ <a class="header-anchor" href="#_1-直接使用物理内存" aria-label="Permalink to &quot;1. 直接使用物理内存？&quot;">​</a></h3><p>我们现在应该明白了计算机世界中的虚拟内存地址的含义及其展现形式。那么既然物理内存地址可以直接定位到数据在内存中的存储位置，那为什么我们不直接使用物理内存地址去访问内存而是选择用虚拟内存地址去访问内存呢？</p><p>让我们先来看下，如果在程序中直接使用物理内存地址会发生什么情况？</p><p>假设现在没有虚拟内存地址，我们在程序中对内存的操作全都都是使用物理内存地址，在这种情况下，程序员就需要精确的知道每一个变量在内存中的具体位置，我们需要手动对物理内存进行布局，明确哪些数据存储在内存的哪些位置，除此之外我们还需要考虑为每个进程究竟要分配多少内存？内存紧张的时候该怎么办？如何避免进程与进程之间的地址冲突？等等一系列复杂且琐碎的细节。</p><p>如果我们在单进程系统中比如嵌入式设备上开发应用程序，系统中只有一个进程，这单个进程独享所有的物理资源包括内存资源。在这种情况下，上述提到的这些直接使用物理内存的问题可能还好处理一些，但是仍然具有很高的开发门槛。</p><p>然而在现代操作系统中往往支持多个进程，需要处理多进程之间的协同问题，在多进程系统中直接使用物理内存地址操作内存所带来的上述问题就变得非常复杂了。</p><p>例如有一个C语言程序：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;stdio.h&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;unistd.h&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> argc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">char</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">argv</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">[]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // ... ...</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	while</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        i</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">++</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        sleep</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>在程序代码相同的情况下，我们用这份代码同时启动三个进程，我们将进程依次命名为 a , b , c 。这三个进程用到的代码是一样的，都是我们提前写好的，可以被多次运行。由于我们是直接操作物理内存地址，假设变量 i 保存在 0x354 这个物理地址上。这三个进程运行起来之后，同时操作这个 0x354 物理地址，这样这个变量 i 的值就会很混乱吗？ 三个进程就会出现变量的地址冲突。</p><img src="`+r+'" alt="image.png" style="zoom:50%;"><p>所以在直接操作物理内存的情况下，我们需要知道每一个变量的位置都被安排在了哪里，而且还要注意和多个进程同时运行的时候，不能共用同一个地址，否则就会造成地址冲突。</p><p>现实中一个程序会有很多的变量和函数，这样一来我们给它们都需要计算一个合理的位置，还不能与其他进程冲突，这就很复杂了。</p><h3 id="_2-程序的局部性" tabindex="-1">2. 程序的局部性 <a class="header-anchor" href="#_2-程序的局部性" aria-label="Permalink to &quot;2. 程序的局部性&quot;">​</a></h3><p>那么该如何解决上边直接使用物理地址而出现的这个问题呢？程序的局部性原理救了我们~~</p><blockquote><p>程序局部性原理表现为：时间局部性和空间局部性。</p><p><strong>时间局部性</strong>是指如果程序中的某条指令一旦执行，则不久之后该指令可能再次被执行；如果某块数据被访问，则不久之后该数据可能再次被访问。</p><p><strong>空间局部性</strong>是指一旦程序访问了某个存储单元，则不久之后，其附近的存储单元也将被访问。</p></blockquote><p>从程序局部性原理的描述中我们可以得出这样一个结论：进程在运行之后，对于内存的访问<strong>不会一下子就要访问全部的内存</strong>，相反进程对于内存的访问会表现出明显的倾向性，更加倾向于访问最近访问过的数据以及热点数据附近的数据。</p><p>根据这个结论我们就清楚了，无论一个进程实际可以占用的内存资源有多大，根据程序局部性原理，在某一段时间内，进程真正需要的物理内存其实是很少的一部分，我们只需要为每个进程分配很少的物理内存就可以保证进程的正常执行运转。</p><h3 id="_3-虚拟内存的引入" tabindex="-1">3. 虚拟内存的引入 <a class="header-anchor" href="#_3-虚拟内存的引入" aria-label="Permalink to &quot;3. 虚拟内存的引入&quot;">​</a></h3><p>虚拟内存的引入正是要解决上述的问题，虚拟内存引入之后，进程的视角就会变得非常开阔，每个进程都拥有自己独立的虚拟地址空间，进程与进程之间的虚拟内存地址空间是相互隔离，互不干扰的。每个进程都认为自己独占所有内存空间，自己想干什么就干什么。</p><p>系统上还运行了哪些进程和自身没有任何关系。这样一来我们就可以将多进程之间协同的相关复杂细节统统交给内核中的内存管理模块来处理，极大地解放了程序员的负担。这一切都是因为虚拟内存能够提供内存地址空间的隔离，极大地扩展了可用空间。</p><img src="'+h+'" alt="image-20221124222104170" style="zoom:50%;"><p>这样进程就以为自己独占了整个内存空间资源，给进程产生了所有内存资源都属于“幻觉”，这其实是 CPU 和操作系统使用的一个障眼法罢了，任何一个虚拟内存里所存储的数据，<strong>本质上还是保存在真实的物理内存里的</strong>。只不过内核帮我们做了虚拟内存到物理内存的这一层映射，将不同进程的虚拟地址和不同内存的物理地址映射起来。</p><p>当 CPU 访问进程的虚拟地址时，经过地址翻译硬件将虚拟地址转换成不同的物理地址，这样不同的进程运行的时候，虽然操作的是同一虚拟地址，但其实背后写入的是不同的物理地址，这样就不会冲突了。</p>',42)])])}const _=a(o,[["render",d]]);export{u as __pageData,_ as default};
